// ─── index.ts ─────────────────────────────────────────────────────────────────
// Public API for the combobox module.
// Uses the Compound Components pattern (Dot Notation) for a clean namespace.
//
// Usage:
//   import { Combobox } from "@/components/ui/combobox"
//   <Combobox.Single ... />
//   <Combobox.Multi ... />
//
// Types are exported separately:
//   import type { ComboboxItem, ComboboxProps, MultiComboboxProps } from "..";

import { MultiCombobox } from "./multi-combobox"
import { SingleCombobox } from "./single-combobox"
import type { ComboboxItem, ComboboxProps, MultiComboboxProps } from "./types"

export const Combobox = {
  Single: SingleCombobox,
  Multi: MultiCombobox,
}

export type { ComboboxItem, ComboboxProps, MultiComboboxProps }

// ─── types.ts ───────────────────────────────────────────────────────────────
// Shared types for the combobox module.

export interface ComboboxItem {
  /** Stable id, if different from `value` (e.g. a database id). */
  id?: string
  /** Unique value used for selection/equality. */
  value: string
  /** Display label. */
  label: string
  /** Present on the synthetic "create new" row appended while typing. */
  creatable?: string
  /** Marks an item that the caller doesn't want edited/deleted inline. */
  isSystem?: boolean
}

export interface ComboboxProps {
  items: ComboboxItem[]
  /** Selected value (matches `ComboboxItem.value`), or "" for none. */
  value: string
  onChange: (value: string) => void
  /** Called when the user commits a typed value that has no matching item. */
  onCreateIntent?: (label: string) => void
  onEditIntent?: (item: ComboboxItem) => void
  onDeleteIntent?: (id: string) => void
  placeholder?: string
  label?: string
  disabled?: boolean
  className?: string
  error?: Array<{ message?: string } | string | undefined>
}

export interface MultiComboboxProps {
  items: ComboboxItem[]
  values: string[]
  onChange: (values: string[]) => void
  onCreateIntent?: (label: string) => void
  onEditIntent?: (item: ComboboxItem) => void
  onDeleteIntent?: (id: string) => void
  placeholder?: string
  label?: string
  disabled?: boolean
  className?: string
  error?: Array<{ message?: string } | string | undefined>
}

// ─── helpers.ts ───────────────────────────────────────────────────────────────
// Pure functions that operate on ComboboxItem arrays.
// No React, no side-effects.

import type { ComboboxItem } from "./types"

/**
 * Canonical normalization for combobox label matching.
 * NFKD decomposition handles homoglyphs (e.g. ℌ → H).
 * Strips zero-width and variation-selector chars that aren't visible.
 */
export function normalizeLabel(input: string): string {
  return input
    .trim()
    .normalize("NFKD")
    .replace(/[​-‍︀-️]/g, "")
    .toLocaleLowerCase()
}

/**
 * Renders a label for display, guarding against empty values and long strings.
 * Falls back to "Untitled" for empty/whitespace-only labels.
 * Truncates with ellipsis when exceeding `maxLength` (default: no truncation).
 */
export function formatItemLabel(label: string, maxLength?: number): string {
  const trimmed = label.trim()
  if (!trimmed) {
    return "Untitled"
  }
  if (maxLength && trimmed.length > maxLength) {
    return `${trimmed.slice(0, maxLength)}…`
  }
  return trimmed
}

/**
 * Build the item list for the combobox view.
 * - When inputValue is non-empty: filter items whose normalized label contains the query
 * - When inputValue is empty: show all items (no filter)
 * - Optionally appends a "create new" sentinel when the typed text has no exact match
 *
 * This replaces Base UI's built-in filter (which is disabled via filter={() => true})
 * so that filtering and creatable logic use consistent normalizeLabel matching.
 */
export function buildItemsForView(
  items: ComboboxItem[],
  inputValue: string,
  hasOnCreate: boolean
): ComboboxItem[] {
  const trimmed = inputValue.trim()
  const lowered = normalizeLabel(trimmed)

  const filtered = trimmed
    ? items.filter((item) => normalizeLabel(item.label).includes(lowered))
    : items

  if (!hasOnCreate || trimmed === "") {
    return filtered
  }

  const exactExists = filtered.some(
    (item) => normalizeLabel(item.label) === lowered
  )

  if (exactExists) {
    return filtered
  }

  return [
    ...filtered,
    {
      creatable: trimmed,
      label: trimmed,
      value: `__create__:${lowered}`,
    },
  ]
}

/** Resolve the id to pass to onDeleteIntent. */
export function resolveDeleteId(item: ComboboxItem): string | undefined {
  return item.id ?? (item.isSystem ? undefined : item.value)
}

/** Normalise the mixed error array the public API accepts. */
export function normalizeErrors(
  error: Array<{ message?: string } | string | undefined> | undefined
): Array<{ message?: string } | undefined> {
  return error?.map((e) => (typeof e === "string" ? { message: e } : e)) ?? []
}

// ─── single-combobox.tsx ──────────────────────────────────────────────────────
// Public-facing single-select combobox.
// Calls useComboboxInteraction for all logic.
// Assembles visual layer components. No business logic, no data mutations.

import { Combobox } from "@base-ui/react/combobox"
import { ChevronDownIcon, XIcon } from "lucide-react"
import { useIsMobile } from "@/hooks/use-media-query"
import { cn } from "@/lib/utils"
import { normalizeErrors } from "./helpers"
import { DesktopInputShell } from "./input-shell"
import {
  DesktopCreatableItem,
  DesktopRegularItem,
} from "./item-visuals.desktop"
import { MobileCreatableItem, MobileRegularItem } from "./item-visuals.mobile"
import {
  DesktopPopoverShell,
  MobileDrawerShell,
} from "./responsive-dropdown-shell"
import type { ComboboxItem, ComboboxProps } from "./types"
import { useSingleComboboxInteraction } from "./use-combobox-interaction"

export function SingleCombobox({
  items,
  value,
  onChange,
  onCreateIntent,
  onEditIntent,
  onDeleteIntent,
  placeholder = "Select or type...",
  label,
  disabled = false,
  className,
  error,
}: ComboboxProps) {
  const isMobile = useIsMobile()

  const {
    inputValue,
    isOpen,
    itemsForView,
    selectedItem,
    isItemEqualToValue,
    itemToStringLabel,
    itemToStringValue,
    onInputValueChange,
    onItemHighlighted,
    onOpenChange,
    onValueChange,
    handleInputKeyDown,
  } = useSingleComboboxInteraction({ items, value, onChange, onCreateIntent })

  const hasError = !!error && error.length > 0
  const normalizedErrors = normalizeErrors(error)

  return (
    <div className={cn("relative w-full", className)}>
      {label && (
        // biome-ignore lint/a11y/noLabelWithoutControl: label is associated via Combobox.Root
        <label className="mb-1.5 block font-medium text-[13px] text-foreground/80">
          {label}
        </label>
      )}

      <Combobox.Root<ComboboxItem>
        disabled={disabled}
        filter={() => true}
        inputValue={inputValue}
        isItemEqualToValue={isItemEqualToValue}
        items={itemsForView}
        itemToStringLabel={itemToStringLabel}
        itemToStringValue={itemToStringValue}
        onInputValueChange={onInputValueChange}
        onItemHighlighted={onItemHighlighted}
        onOpenChange={onOpenChange}
        onValueChange={onValueChange}
        open={isOpen}
        value={selectedItem}
      >
        {isMobile ? (
          <>
            {/* Mobile: read-only trigger button that opens the sheet */}
            <Combobox.Trigger
              className={cn(
                "group flex min-h-9 w-full items-center rounded-lg border border-input bg-input/30",
                "transition-all focus-within:ring-[3px] focus-within:ring-ring/30",
                "data-[disabled]:cursor-not-allowed data-[disabled]:opacity-50",
                hasError &&
                  "border-destructive focus-within:ring-destructive/30"
              )}
              render={<button type="button" />}
            >
              <span
                className={cn(
                  "flex-1 px-3 text-start text-sm outline-none",
                  !selectedItem && "text-muted-foreground"
                )}
              >
                {selectedItem ? selectedItem.label : placeholder}
              </span>

              {selectedItem && (
                // biome-ignore lint/a11y/useSemanticElements: <explanation>
                <div
                  className="me-0.5 flex h-6 w-6 shrink-0 items-center justify-center rounded-md text-muted-foreground transition-colors hover:text-foreground"
                  onClick={(e) => {
                    e.stopPropagation()
                    onChange("")
                  }}
                  onKeyDown={(e) => {
                    if (e.key === "Enter") {
                      e.stopPropagation()
                      onChange("")
                    }
                  }}
                  role="button"
                  tabIndex={0}
                >
                  <XIcon className="h-3.5 w-3.5" />
                </div>
              )}

              <div className="flex h-full w-8 shrink-0 items-center justify-center rounded-e-lg text-muted-foreground transition-colors hover:text-foreground">
                <ChevronDownIcon
                  className={cn(
                    "h-4 w-4 transition-transform duration-150",
                    isOpen && "rotate-180"
                  )}
                />
              </div>
            </Combobox.Trigger>

            <MobileDrawerShell
              onInputKeyDown={handleInputKeyDown}
              onOpenChange={onOpenChange}
              open={isOpen}
              placeholder={placeholder}
              sheetHeight="80vh"
            >
              {(item: ComboboxItem) =>
                item.creatable ? (
                  <MobileCreatableItem item={item} key={item.value} />
                ) : (
                  <MobileRegularItem
                    isSelected={item.value === value}
                    item={item}
                    key={item.value}
                    onDeleteIntent={onDeleteIntent}
                    onEditIntent={onEditIntent}
                  />
                )
              }
            </MobileDrawerShell>
          </>
        ) : (
          <>
            <DesktopInputShell
              error={hasError}
              onInputKeyDown={handleInputKeyDown}
              placeholder={placeholder}
            />
            <DesktopPopoverShell>
              {(item: ComboboxItem) =>
                item.creatable ? (
                  <DesktopCreatableItem item={item} key={item.value} />
                ) : (
                  <DesktopRegularItem
                    item={item}
                    key={item.value}
                    onDeleteIntent={onDeleteIntent}
                    onEditIntent={onEditIntent}
                  />
                )
              }
            </DesktopPopoverShell>
          </>
        )}
      </Combobox.Root>

      {hasError && (
        <p className="mt-1.5 text-destructive text-xs">
          {normalizedErrors.find((e) => e?.message)?.message}
        </p>
      )}
    </div>
  )
}

// ─── multi-combobox.tsx ───────────────────────────────────────────────────────
// Public-facing multi-select combobox.
// Calls useMultiComboboxInteraction for all logic.
// Fires onEditIntent / onDeleteIntent — the parent owns those side-effects.

import { Combobox } from "@base-ui/react/combobox"
import { ChevronDownIcon, XIcon } from "lucide-react"
import { useIsMobile } from "@/hooks/use-media-query"
import { cn } from "@/lib/utils"
import { formatItemLabel, normalizeErrors } from "./helpers"
import { DesktopChipsInput } from "./input-shell"
import {
  DesktopCreatableItem,
  DesktopRegularItem,
} from "./item-visuals.desktop"
import { MobileCreatableItem, MobileRegularItem } from "./item-visuals.mobile"
import {
  DesktopPopoverShell,
  MobileDrawerShell,
} from "./responsive-dropdown-shell"
import type { ComboboxItem, MultiComboboxProps } from "./types"
import { useMultiComboboxInteraction } from "./use-combobox-interaction"

export function MultiCombobox({
  items,
  values,
  onChange,
  onCreateIntent,
  onEditIntent,
  onDeleteIntent,
  placeholder = "Select or type...",
  label,
  disabled = false,
  className,
  error,
}: MultiComboboxProps) {
  const isMobile = useIsMobile()

  const {
    inputValue,
    isOpen,
    itemsForView,
    selectedItems,
    isItemEqualToValue,
    itemToStringLabel,
    itemToStringValue,
    onInputValueChange,
    onItemHighlighted,
    onOpenChange,
    onValueChange,
    handleInputKeyDown,
  } = useMultiComboboxInteraction({
    items,
    values,
    onChange,
    onCreateIntent,
  })

  const hasError = !!error && error.length > 0
  const normalizedErrors = normalizeErrors(error)

  return (
    <div className={cn("relative w-full", className)}>
      {label && (
        // biome-ignore lint/a11y/noLabelWithoutControl: label is associated via Combobox.Root
        <label className="mb-1.5 block font-medium text-[13px] text-foreground/80">
          {label}
        </label>
      )}

      <Combobox.Root<ComboboxItem, true>
        disabled={disabled}
        filter={() => true}
        inputValue={inputValue}
        isItemEqualToValue={isItemEqualToValue}
        items={itemsForView}
        itemToStringLabel={itemToStringLabel}
        itemToStringValue={itemToStringValue}
        multiple
        onInputValueChange={onInputValueChange}
        onItemHighlighted={onItemHighlighted}
        onOpenChange={onOpenChange}
        onValueChange={onValueChange}
        open={isOpen}
        value={selectedItems}
      >
        {isMobile ? (
          <>
            {/* Mobile: read-only trigger chip-display that opens the sheet */}
            <Combobox.Trigger
              className={cn(
                "group flex min-h-9 w-full items-center rounded-lg border border-input bg-input/30 px-2 py-1",
                "transition-all focus-within:ring-[3px] focus-within:ring-ring/30",
                "data-[disabled]:cursor-not-allowed data-[disabled]:opacity-50",
                hasError &&
                  "border-destructive focus-within:ring-destructive/30"
              )}
              render={<button type="button" />}
            >
              <div className="flex flex-1 flex-wrap items-center gap-1 text-start">
                {selectedItems.length > 0 ? (
                  selectedItems.map((item) => (
                    <span
                      className="flex max-w-[200px] cursor-default items-center gap-1 truncate rounded-md bg-secondary px-2 py-0.5 font-medium text-secondary-foreground text-xs"
                      key={item.value}
                      onClick={(e) => e.stopPropagation()}
                    >
                      {formatItemLabel(item.label)}
                      <div
                        className="ms-0.5 flex items-center justify-center rounded p-0.5 opacity-60 transition-opacity hover:opacity-100"
                        onClick={(e) => {
                          e.stopPropagation()
                          onChange(values.filter((v) => v !== item.value))
                        }}
                        onKeyDown={(e) => {
                          if (e.key === "Enter") {
                            e.stopPropagation()
                            onChange(values.filter((v) => v !== item.value))
                          }
                        }}
                        role="button"
                        tabIndex={0}
                      >
                        <XIcon className="h-3 w-3" />
                      </div>
                    </span>
                  ))
                ) : (
                  <span className="px-1 text-muted-foreground text-sm outline-none">
                    {placeholder}
                  </span>
                )}
              </div>

              <div className="flex shrink-0 items-center">
                {selectedItems.length > 0 && (
                  <div
                    className="me-0.5 flex h-6 w-6 items-center justify-center rounded-md text-muted-foreground transition-colors hover:text-foreground"
                    onClick={(e) => {
                      e.stopPropagation()
                      onChange([])
                    }}
                    onKeyDown={(e) => {
                      if (e.key === "Enter") {
                        e.stopPropagation()
                        onChange([])
                      }
                    }}
                    role="button"
                    tabIndex={0}
                  >
                    <XIcon className="h-3.5 w-3.5" />
                  </div>
                )}
                <div className="flex h-6 w-8 items-center justify-center rounded-e-lg text-muted-foreground transition-colors hover:text-foreground">
                  <ChevronDownIcon
                    className={cn(
                      "h-4 w-4 transition-transform duration-150",
                      isOpen && "rotate-180"
                    )}
                  />
                </div>
              </div>
            </Combobox.Trigger>

            <MobileDrawerShell
              onInputKeyDown={handleInputKeyDown}
              onOpenChange={onOpenChange}
              open={isOpen}
              placeholder={placeholder}
              sheetHeight="80vh"
            >
              {(item: ComboboxItem) =>
                item.creatable ? (
                  <MobileCreatableItem item={item} key={item.value} />
                ) : (
                  <MobileRegularItem
                    isSelected={values.includes(item.value)}
                    item={item}
                    key={item.value}
                    onDeleteIntent={onDeleteIntent}
                    onEditIntent={onEditIntent}
                  />
                )
              }
            </MobileDrawerShell>
          </>
        ) : (
          <>
            <DesktopChipsInput
              error={hasError}
              onInputKeyDown={handleInputKeyDown}
              placeholder={placeholder}
              renderChips={(inputNode) => (
                <>
                  {selectedItems.map((item) => (
                    <Combobox.Chip
                      aria-label={item.label}
                      className={cn(
                        "flex items-center gap-1 rounded-md bg-secondary px-2 py-0.5",
                        "font-medium text-secondary-foreground text-xs",
                        "max-w-[200px] cursor-default truncate outline-none",
                        "data-[highlighted]:bg-primary data-[highlighted]:text-primary-foreground"
                      )}
                      key={item.value}
                    >
                      {formatItemLabel(item.label)}
                      <Combobox.ChipRemove
                        aria-label={`Remove ${item.label}`}
                        className="ms-0.5 rounded p-0.5 opacity-60 transition-opacity hover:opacity-100"
                      >
                        <XIcon className="h-3 w-3" />
                      </Combobox.ChipRemove>
                    </Combobox.Chip>
                  ))}
                  {inputNode}
                </>
              )}
            />

            <DesktopPopoverShell>
              {(item: ComboboxItem) =>
                item.creatable ? (
                  <DesktopCreatableItem item={item} key={item.value} />
                ) : (
                  <DesktopRegularItem
                    item={item}
                    key={item.value}
                    onDeleteIntent={onDeleteIntent}
                    onEditIntent={onEditIntent}
                  />
                )
              }
            </DesktopPopoverShell>
          </>
        )}
      </Combobox.Root>

      {hasError && (
        <p className="mt-1.5 text-destructive text-xs">
          {normalizedErrors.find((e) => e?.message)?.message}
        </p>
      )}
    </div>
  )
}

// ─── input-shell.tsx ──────────────────────────────────────────────────────────
// Purely visual input wrappers. Accept callbacks from the interaction layer,
// render Base UI input nodes and icons. Zero state. Zero logic.

import { Combobox } from "@base-ui/react/combobox"
import { ChevronDownIcon, SearchIcon, XIcon } from "lucide-react"
import { forwardRef, type ReactNode } from "react"
import { cn } from "@/lib/utils"

// ─── Desktop: single-select trigger + text input ──────────────────────────────

export function DesktopInputShell({
  placeholder,
  children,
  error = false,
  onInputKeyDown,
}: {
  placeholder: string
  children?: ReactNode
  error?: boolean
  onInputKeyDown?: (e: React.KeyboardEvent<HTMLInputElement>) => void
}) {
  return (
    <Combobox.InputGroup
      className={cn(
        "group flex min-h-9 w-full items-center rounded-xl border border-input bg-input/30",
        "transition-all focus-within:ring-[3px] focus-within:ring-ring/50",
        "data-[disabled]:cursor-not-allowed data-[disabled]:opacity-50",
        error && "border-destructive focus-within:ring-destructive/30"
      )}
    >
      {children}
      <Combobox.Input
        aria-invalid={error}
        className="h-9 min-w-24 flex-1 bg-transparent px-3 text-foreground text-sm outline-none placeholder:text-muted-foreground"
        onKeyDown={onInputKeyDown}
        placeholder={placeholder}
      />

      {/* Divider between input and controls */}
      <span className="h-4 w-px shrink-0 bg-border/50" />

      <Combobox.Clear
        className={cn(
          "mx-1 flex h-6 w-6 shrink-0 items-center justify-center rounded-lg",
          "text-muted-foreground transition-colors hover:bg-foreground/8 hover:text-foreground"
        )}
      >
        <XIcon className="h-3.5 w-3.5" />
      </Combobox.Clear>

      <Combobox.Trigger
        className={cn(
          "me-1 flex h-7 w-7 shrink-0 items-center justify-center rounded-lg",
          "text-muted-foreground transition-colors hover:bg-foreground/8 hover:text-foreground"
        )}
      >
        <Combobox.Icon>
          <ChevronDownIcon className="h-4 w-4 transition-transform duration-150 group-data-[popup-open]:rotate-180" />
        </Combobox.Icon>
      </Combobox.Trigger>
    </Combobox.InputGroup>
  )
}

// ─── Mobile: pill-shaped search bar inside the sheet ──────────────────────────
export const MobileSearchBar = forwardRef<
  HTMLInputElement,
  {
    placeholder: string
    onInputKeyDown?: (e: React.KeyboardEvent<HTMLInputElement>) => void
  }
>(({ placeholder, onInputKeyDown }, ref) => (
  <div className="shrink-0 border-b px-4 py-3">
    <Combobox.InputGroup
      className={cn(
        "flex h-12 w-full items-center gap-2 rounded-full",
        "border border-input bg-input/30 px-4",
        "transition-all focus-within:ring-[3px] focus-within:ring-ring/50"
      )}
    >
      <SearchIcon className="h-4 w-4 shrink-0 text-muted-foreground" />
      <Combobox.Input
        className="flex-1 bg-transparent text-base outline-none placeholder:text-muted-foreground"
        onKeyDown={onInputKeyDown}
        placeholder={placeholder}
        ref={ref}
      />
      <Combobox.Clear className="flex h-6 w-6 shrink-0 items-center justify-center rounded-full text-muted-foreground transition-colors hover:text-foreground">
        <XIcon className="h-3.5 w-3.5" />
      </Combobox.Clear>
    </Combobox.InputGroup>
  </div>
))
MobileSearchBar.displayName = "MobileSearchBar"

// ─── Desktop: multi-select chips + inline input ────────────────────────────────
export function DesktopChipsInput({
  placeholder,
  error = false,
  onInputKeyDown,
  renderChips,
}: {
  placeholder: string
  error?: boolean
  onInputKeyDown?: (e: React.KeyboardEvent<HTMLInputElement>) => void
  renderChips: (inputNode: ReactNode) => ReactNode
}) {
  return (
    <Combobox.InputGroup
      className={cn(
        "group flex min-h-9 w-full flex-wrap items-center gap-1 rounded-xl border border-input bg-input/30 px-2 py-1",
        "transition-all focus-within:ring-[3px] focus-within:ring-ring/50",
        "data-[disabled]:cursor-not-allowed data-[disabled]:opacity-50",
        error && "border-destructive focus-within:ring-destructive/30"
      )}
    >
      <Combobox.Chips className="contents">
        <Combobox.Value>
          {(val: unknown[]) =>
            renderChips(
              <Combobox.Input
                className="h-7 min-w-20 flex-1 bg-transparent text-foreground text-sm outline-none placeholder:text-muted-foreground"
                onKeyDown={onInputKeyDown}
                placeholder={val.length > 0 ? "" : placeholder}
              />
            )
          }
        </Combobox.Value>
      </Combobox.Chips>

      {/* Divider between chips/input and controls */}
      <span className="h-4 w-px shrink-0 bg-border/50" />

      <Combobox.Clear
        className={cn(
          "flex h-6 w-6 shrink-0 items-center justify-center rounded-lg",
          "text-muted-foreground transition-colors hover:bg-foreground/8 hover:text-foreground"
        )}
      >
        <XIcon className="h-3.5 w-3.5" />
      </Combobox.Clear>

      <Combobox.Trigger
        className={cn(
          "me-0.5 flex h-6 w-7 shrink-0 items-center justify-center rounded-lg",
          "text-muted-foreground transition-colors hover:bg-foreground/8 hover:text-foreground"
        )}
      >
        <Combobox.Icon>
          <ChevronDownIcon className="h-4 w-4 transition-transform duration-150 group-data-[popup-open]:rotate-180" />
        </Combobox.Icon>
      </Combobox.Trigger>
    </Combobox.InputGroup>
  )
}

// ─── item-visuals.desktop.tsx ─────────────────────────────────────────────────
// Purely presentational desktop list row components.
// Zero state. Zero business logic. Only renders Base UI nodes + icons.

import { Combobox } from "@base-ui/react/combobox"
import { PlusIcon, PencilIcon, TrashIcon, CheckIcon } from "lucide-react"
import { Button } from "@/components/ui/button"
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip"
import { cn } from "@/lib/utils"
import { formatItemLabel, resolveDeleteId } from "./helpers"
import type { ComboboxItem } from "./types"

// ─── Creatable sentinel row ────────────────────────────────────────────────────

export function DesktopCreatableItem({ item }: { item: ComboboxItem }) {
  return (
    <Combobox.Item
      className={cn(
        "relative flex cursor-default select-none items-center gap-2.5",
        "rounded-xl py-2 ps-2.5 pe-2.5 text-sm outline-none",
        "text-emerald-600 dark:text-emerald-400",
        "transition-colors data-highlighted:bg-emerald-500/10"
      )}
      value={item}
    >
      <span className="flex h-5 w-5 shrink-0 items-center justify-center rounded-lg bg-emerald-500/15">
        <PlusIcon className="h-3 w-3" />
      </span>
      <span>
        New:{" "}
        <span className="font-semibold">
          {formatItemLabel(item.creatable ?? "", 60)}
        </span>
      </span>
    </Combobox.Item>
  )
}

// ─── Regular item row ─────────────────────────────────────────────────────────

export function DesktopRegularItem({
  item,
  onEditIntent,
  onDeleteIntent,
}: {
  item: ComboboxItem
  onEditIntent?: (item: ComboboxItem) => void
